function field(k,label,min,max,step=100,unit='mm',help='',slider=true){return `<div class="field" data-field="${k}"><div class="parameter-row"><label class="field-label" for="n-${k}"><span>${label}</span><code>${k==='SiteL'?'L':k}</code></label><div class="value-row"><input id="n-${k}" data-param="${k}" type="number" min="${min}" max="${max}" step="${step}" value="${c[k]}" aria-describedby="help-${k}"><span>${unit}</span></div></div>${slider?`<input aria-label="${label}滑块" data-range="${k}" type="range" min="${min}" max="${max}" step="${step}" value="${c[k]}">`:''}<small id="help-${k}">${help}</small></div>`;}
function select(k,label,options,help=''){return `<div class="field"><label class="field-label" for="s-${k}"><span>${label}</span><code>${k}</code></label><select id="s-${k}" data-select="${k}">${options.map((s,i)=>`<option value="${i}" ${c[k]===i?'selected':''}>${s}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</div>`;}
function toggle(k,label,help){return `<label class="toggle-field" for="t-${k}"><span><strong>${label}</strong><small>${help}</small></span><input id="t-${k}" data-toggle="${k}" type="checkbox" ${c[k]?'checked':''}></label>`;}
function fold(title,body){return `<details><summary>${title}</summary>${body}</details>`;}

function windControls(){
 const signed=(k,label)=>field(k,label,-5,5,.1,'','正值向内受压；负值向外吸力。',false);
 return fold('风向与分区',select('WindModel','荷载模式',['旧版 · 整面下压 / 吸力','风向分区 · 用户净压系数'])+(c.WindModel===0?
 field('Cp','整面下压系数',0,5,.1,'','旧版独立工况，不区分来风方向。',false)+field('Cs','整面吸力系数',-5,0,.1,'','可切换风向分区模式。',false):
 select('WindDirection','水平吹向',['横向 · −X → +X','横向 · +X → −X','纵向 · −Y → +Y','纵向 · +Y → −Y','自定义角度'],'X 跨拱，Y 沿首榀轴线；曲轴也使用固定全局方向。')+
 (c.WindDirection===4?field('WindAngle','吹向角',0,360,5,'°','0° 吹向 +X；90° 吹向 +Y。',false):'')+
 toggle('WindReverse','同时校核反向风','所选方向及其反向分别计算，再取结果包络。')+
 select('WindEnds','端面受风',['敞开屋面 · 无端面','加两端荷载面'],'默认敞开。端面只增加荷载，不增加墙体刚度；侧墙和内压需另行处理。')+
 signed('WindRoofWindward','屋面 · 迎风区')+signed('WindRoofLeeward','屋面 · 背风区')+signed('WindRoofParallel','屋面 · 平行区')+
 (c.WindEnds===1?signed('WindEndWindward','端面 · 迎风区')+signed('WindEndLeeward','端面 · 背风区')+signed('WindEndParallel','端面 · 平行区'):'')+
 '<p class="hint">演示系数须按项目核定。按面朝向分区，非规范边角分区；迎风屋面也可设为吸力。敞开屋面系数表示上下表面合成净压。等高直轴屋面在纵向来风时属于平行区，仍可有法向吸力，未计切向风阻。</p>'));
}

function windResultControls(shown){
 const cases=shown?.wind?.cases||[];
 if(!cases.length)return `<p class="hint">${c.W0===0?'基本风压为 0：本次未施加任何风荷载。':'切换风向分区并重新计算，可查看荷载箭头。'}</p>`;
 const w=cases[windCaseIndex]||cases[0];
 const pressures=w.zones.map(z=>`${z.surface==='roof'?'屋面':z.surface==='front-end'?'前端':'后端'}${{windward:'迎风',leeward:'背风',parallel:'平行'}[z.zone]}：${z.pressureKNm2.toFixed(2)} kN/m²`).join('；');
 return `<div class="wind-result"><button id="windView" aria-pressed="${windView}">${windView?'关闭风荷载图':'查看风荷载分区与箭头'}</button>${cases.length>1?`<label for="windCase">查看风工况</label><select id="windCase">${cases.map((w,i)=>`<option value="${i}" ${w.id===(cases[windCaseIndex]||cases[0]).id?'selected':''}>${esc(w.label)}</option>`).join('')}</select>`:''}<p>${esc(w.label)}</p><small>${esc(pressures)}</small>${windView?'<p class="wind-key"><b class="wind-positive">红：向内受压</b> · <b class="wind-negative">蓝：向外吸力</b><br>灰：零荷载；绿色箭头：水平吹向。<br>箭头仅示方向，非位移或应力。</p>':''}<small>风合力 X / Y / Z：${[w.forceKN.x,w.forceKN.y,w.forceKN.z].map(x=>x.toFixed(2)).join(' / ')} kN</small></div>`;
}
