function paintEditor(refit=false){
 document.body.classList.add('editor-mode');
 if(stage===5){$('#stepTitle').textContent='编辑已选方案';$('#stepIntro').textContent='按当前输入验算，与修改前的应力对照。';}
 const roof=stage===6,r=roof?editor.roofCandidate:editor.current,max=editor.sharedMax;const params=roof?r?.parameters:editor.parameters;error=editor.validate(ArchCore,params);
 try{model=error?null:stressModel(ArchCore,{...params,...Object.fromEntries(displayKeys.map(k=>[k,c[k]]))},r,{roof,stress:editor.stress&&!roof,max});}catch(e){error=e.message;model=null;}
 let before=null;
 if(stage===5&&editor.compare&&model&&editor.before?.solved){try{before=stressModel(ArchCore,editor.record.base,editor.before,{stress:editor.stress,max});}catch(e){error='基准预览失败：'+e.message;}}
 const paired=!!before;view.comparisonPadding=paired?1.18:1;view.needFit=refit;view.setModel(paired?before:model,stage===5&&singleFrame&&!paired,paired?model:null);
 $('#viewport').classList.toggle('dual-view',paired);$('#comparisonOverlay').hidden=!paired;if(paired)$('#comparisonOverlay').innerHTML=comparisonHtml(editor,ArchCore.names);
 $('#singleFrame').hidden=stage!==5;$('#singleFrame').disabled=paired;$('#singleFrame').classList.toggle('active',singleFrame);$('#singleFrame').setAttribute('aria-pressed',String(singleFrame));$('#singleFrame').textContent=singleFrame?'返回阵列':'查看单榀';
 $('#modelTitle').textContent=ArchCore.names[editor.record.type];$('#modelTag').textContent=stage===6?`${editor.selectedSide==='before'?'修改前方案':'当前方案'} · ${roofStatus(r,editor.verified,editor.selectedSide).screeningStatus} · 屋面仅外观`:paired?'修改前 / 修改后 · 同一色标与尺度':'用户编辑方案 · '+(r?.solved?'已计算':'待重新计算');
 $('#modelStatus').textContent=error?'参数需调整':roof?roofStatus(r,editor.verified,editor.selectedSide).screeningStatus:editedStateLabel(editor);
 $('#geometryError').hidden=!error;$('#geometryError').textContent=error;$('#arrayRelation').hidden=true;
 $('#metrics').hidden=paired;$('#metrics').innerHTML=[['最大位移',r?.displacementMm,'mm'],['最大正应力',r?.stressMPa,'MPa'],['全部杆件质量',r?.massKg,'kg']].map(([n,v,u])=>`<div class="metric"><small>${n}</small><strong>${fmt(r?.solved?v:null)}</strong><em>${u}</em></div>`).join('');
 $('#stressLegend').hidden=!(stage===5&&editor.stress&&(paired||r?.solved));$('#stressHigh').textContent=fmt(max)+' MPa';$('#stressLegend small').innerHTML='修改前 / 后共用色标 · 非安全等级<br>逐梁正应力绝对值包络';
 $('#roofToggle').disabled=stage!==6;$('#next').disabled=!editor.roofCandidate||!!editor.validate(ArchCore,editor.roofCandidate.parameters)||editor.busy||rhinoBusy;$('#next').textContent=stage===6?'导出所选方案 .3dm':'按所选方案生成屋面 →';
 $('#undo').disabled=editor.busy||!editor.history.length;$('#exportC').disabled=!editor.roofCandidate||editor.busy;$('#exportB').disabled=!analysis.fresh||!analysis.result?.B||analysis.busy||editor.busy;
 if(stage===5){
  $('#roofChoice').innerHTML=roofChoiceHtml(editor);$('#editorState').innerHTML=editorStatus(editor,error);$('#editorSolve').disabled=!!error||editor.busy;$('#editorSolve').textContent=editor.busy?'正在计算…':!editor.verified?(editor.changes.length?'复核基准与当前修改':'复核所选方案'):editor.changes.length?'计算当前修改':'重新复核当前方案';
  $('#editorCancel').hidden=!editor.busy;$('#editorUndo').disabled=editor.busy||!editor.history.length;$('#editorReset').disabled=editor.busy||!editor.changes.length;
  $('#editorCompare').setAttribute('aria-pressed',String(editor.compare));$('#editorStress').setAttribute('aria-pressed',String(editor.stress));
  $('#editorRecommend').disabled=editor.busy||!analysis.fresh||(!analysis.result?.B?.pass&&!relativeCandidate(analysis.result));$('#editorRecommend').textContent=analysis.result?.B?'切回系统推荐':'切回相对优选';$('#editorBack').disabled=editor.busy;$('#editorExport').disabled=editor.busy||!editor.current?.solved||!editor.before?.solved;
  $('#editorDelta').innerHTML=editorDelta();$('#editorGh').disabled=!editor.before?.solved||editor.busy||!!editor.validate(ArchCore);$$('[data-edit]').forEach(e=>{const f=e.closest('.editor-field'),change=editor.changes.find(x=>x.key===e.dataset.edit);f.classList.toggle('changed',!!change);const label=f.querySelector('.field-baseline');label.textContent=change?'修改前：'+change.before+(change.unit?' '+change.unit:''):'';});
  $('#editorChanges').innerHTML=changesHtml(editor);$('#editorChangeCount').textContent=editor.changes.length?`(${editor.changes.length})`:'';$$('[data-edit]').forEach(e=>e.disabled=editor.busy);
 }else{
  $('#selectionSummary').innerHTML=selectionHtml(editor.roofCandidate);$('#rhinoExport').disabled=!editor.roofCandidate||rhinoBusy;$('#saveSnapshot').disabled=!editor.roofCandidate;
  $$('[data-editor-reopen]').forEach(e=>e.onclick=()=>go(5));$$('[data-return]').forEach(e=>{e.disabled=!analysis.fresh||!analysis.result?.B?.pass;e.onclick=()=>{editor.active=false;choose('recommended');controls();paint(true);};});
 }
 $$('[data-roof-choice]').forEach(e=>e.onclick=()=>{if(editor.selectForRoof(e.dataset.roofChoice)){paint();store();toast('已选'+(editor.selectedSide==='before'?'修改前方案':'当前方案')+'，可点击右下角生成屋面。');}});
 refreshPresentation();refreshGuidance();captureUI?.refresh();
}
function editorCaptureContext(){
 const pair=stage===5&&!!view.comparison,r=stage===6?editor.roofCandidate:editor.current;
 return {cases:pair?['修改前','修改后']:['用户编辑'],valid:!!model,presentationNote:model&&view.displayMode==='schematic'?presentationNote:'',
  labels:pair?[`${ArchCore.names[editor.record.type]} · 修改前基准`,`${ArchCore.names[editor.record.type]} · 修改后 · ${editedStateLabel(editor)}`]:[`${ArchCore.names[editor.record.type]} · ${roofStatus(r,editor.verified,editor.selectedSide).screeningStatus}`],
  stress:stage===5&&editor.stress&&(pair||!!r?.solved),maxStress:editor.sharedMax,windLabel:''};
}

function editorDelta(){
 const a=editor.current,b=editor.before;if(!a?.solved||!b?.solved)return '';
 const rows=[['最大位移',a.displacementMm-b.displacementMm,'mm'],['最大正应力',a.stressMPa-b.stressMPa,'MPa'],['全部杆件质量',a.massKg-b.massKg,'kg']];
 return `<strong>相对修改前的变化</strong><dl>${rows.map(([n,v,u])=>`<dt>${n}</dt><dd>${v>0?'+':''}${fmt(v)} ${u}</dd>`).join('')}</dl><small>数值增减不单独代表是否通过初筛。</small>`;
}
function exportGh(){try{const r=editor.active?editor.before:chosen();if(!r?.solved)throw Error('请先选择已计算的方案或改进起点。');if(editor.active&&editor.validate(ArchCore))throw Error(editor.validate(ArchCore));const before=editor.active?editor.record.base:r.parameters;const after=editor.active?(stage===6?editor.roofCandidate.parameters:editor.parameters):r.parameters;saveFile('竹拱_GH方案参数包.txt',ghExchange(before,after,ArchCore),'text/plain');$('#exportDialog').close();toast('GH 参数包已导出；接入配套 GH 的“App参数包”面板后重算。');}catch(e){toast(e.message);}}
function refreshGuidance(){
 const edit=editor.active&&stage===5,r=chosen(),busy=editor.active?editor.busy:analysis.busy;for(const id of ['loadFiveDemo','restoreDemoBackup'])if($('#'+id))$('#'+id).disabled=busy;
 const guide=workflowGuide({stage,error,busy,fresh:analysis.fresh,selected:r,recommended:analysis.result?.B,improvement:relativeCandidate(analysis.result),editor:edit,editorCurrent:editor.current,editorUsable:editor.usable,roofCandidate:editor.roofCandidate,selectedSide:editor.selectedSide,changes:editor.changes.length,hasBaseline:!!editor.before,verified:editor.verified});
 $('#workflowTitle').textContent=r&&!edit&&stage===5?'已选：'+ArchCore.names[r.type]:guide.title;$('#workflowNote').textContent=guide.note;
 const nav=$('#phaseNav');nav.hidden=stage!==5;if(stage===5){const active=edit?'edit':analysisPanel;nav.innerHTML=[['setup','1','设置'],['results','2','选型'],['edit','3','编辑']].map(([id,n,name])=>`<button data-phase="${id}" ${id===active?'aria-current="step"':''} ${busy||id==='results'&&!analysis.fresh||id==='edit'&&!r&&!edit?'disabled':''}><span>${n}</span>${name}</button>`).join('');$$('[data-phase]').forEach(e=>e.onclick=()=>{if(e.dataset.phase==='edit'){if(!editor.active)startEditor();return;}editor.active=false;analysisPanel=e.dataset.phase;controls();paint();$('#controls').scrollTop=0;});}
 $('#workflowPrimary').hidden=edit;$('#editorSolve').hidden=!edit;$('#editorCancel').hidden=!(edit&&editor.busy);
 const primary=$('#workflowPrimary');primary.textContent=guide.label;primary.disabled=!!guide.disabled||rhinoBusy;
 primary.onclick=()=>{switch(guide.action){case 'solve':$('#solveNow')?.click();break;case 'improve':startImprovement(relativeCandidate(analysis.result).type);break;case 'adopt':choose('recommended');break;case 'edit':startEditor();break;case 'settings':analysisPanel='setup';controls();paint();$('#controls').scrollTop=0;break;case 'selection':go(5);break;case 'export':exportRhino();break;case 'next':go(stage+1);break;}};
 if(stage===5&&!edit&&!analysis.connected&&!analysis.fresh&&!analysis.busy){primary.textContent='连接 Karamba3D';primary.disabled=false;primary.onclick=()=>analysis.connect();$('#workflowTitle').textContent='先连接，再计算';$('#workflowNote').textContent='在 Rhino 运行 BambooKarambaStart，然后重新连接。';}
 const sec=$('#workflowSecondary');sec.hidden=true;
 if(edit){$('#editorSolve').hidden=false;if(editor.roofCandidate){sec.hidden=false;sec.textContent='按所选方案生成屋面 →';sec.onclick=()=>go(6);}else if(editor.canResume(parameterKey(c))&&!editor.before){/* compute is already primary */}}
 else if(stage===5&&editor.canResume(parameterKey(c))){sec.hidden=false;sec.textContent='继续上次编辑 →';sec.onclick=()=>{editor.active=true;go(5);};}
 if(stage===5&&!edit&&analysisPanel==='setup'&&analysis.fresh){primary.textContent='按这些条件重新计算';primary.onclick=()=>$('#solveNow').click();sec.hidden=false;sec.textContent='返回已计算的选型结果 →';sec.onclick=()=>{analysisPanel='results';controls();paint();};}
 if(stage===5&&!edit&&analysis.busy){sec.hidden=false;sec.textContent='取消计算';sec.onclick=()=>analysis.cancel();}
 $('#nextReason').textContent=$('#next').disabled?(error?'先修正左侧参数':busy?'等待本次计算完成':edit?'当前方案待计算；可采用修改前方案':'先在第五步计算并采用方案'):stage===5?(edit?`${editor.selectedSide==='before'?'已选修改前方案':'已选当前方案'} · ${roofStatus(editor.roofCandidate,editor.verified,editor.selectedSide).screeningStatus}`:'已选 '+ArchCore.names[r.type]):'';
 if(stage===5&&!edit&&analysisPanel==='setup'&&!analysis.busy&&analysis.connected){const issue=searchIssue();if(issue){primary.disabled=true;$('#workflowTitle').textContent='搜索设置需调整';$('#workflowNote').textContent=issue;}}
 $('#next').title=$('#nextReason').textContent;$('#exportGh').disabled=busy||!(editor.active?editor.before?.solved&&!editor.validate(ArchCore):r);
}

function candidateField(k){
 const s=listSpecs[k],raw=listDrafts.get(k)??c[k].join(', ');
 return `<div class="candidate-field"><label for="list-${k}">${s.label} <small>${s.unit}</small></label><input id="list-${k}" data-search-list="${k}" type="text" value="${esc(raw)}" aria-describedby="list-help-${k}" aria-invalid="${listErrors.has(k)}"><small id="list-help-${k}" data-list-feedback="${k}">${esc(listErrors.get(k)||candidateHint(k))}</small></div>`;
}
function candidateHint(k){const a=c[k];return `${a.length===1?'固定值':a.length+' 个候选'} · ${k==='Diameters'?'基准仍用材料设置中的初始外径':'基准取首值 '+a[0]} · ${listSpecs[k].min}—${listSpecs[k].max}${listSpecs[k].even?'，偶数':''}`;}
function searchIssue(){if(listErrors.size)return '候选列表需调整：'+[...listErrors.keys()].map(k=>listSpecs[k].label).join('、');try{const p=searchPlan(c);return p.overBudget?`共 ${p.total} 个组合，超过预算 ${p.maximum}；请减少候选值或提高预算（上限 2000）。`:'';}catch(e){return e.message;}}
function refreshSearchPlan(){const box=$('#searchPlan');if(!box)return;try{const p=searchPlan(c),issue=searchIssue();box.classList.toggle('invalid',!!issue);box.innerHTML=`<div class="search-plan-total"><strong>${listErrors.size?'待修正':p.total}</strong><span>候选组合 / 预算 ${p.maximum}</span></div><p>${p.factors.length} 个高度 × ${p.lists.Diameters.length} 个外径 × 各型构造组合</p><div class="search-plan-types">${p.byType.map(t=>`<span>${ArchCore.names[t.type]} <b>${t.count}</b></span>`).join('')}</div><small>${issue?esc(issue):'分别计算各构型基准；相同候选复用结果。不会按列表顺序截断搜索。'}</small>`;}catch(e){box.classList.add('invalid');box.innerHTML='<strong>搜索设置需调整</strong><p>'+esc(e.message)+'</p>';}}
function bindCandidateFields(){
 $$('[data-search-list]').forEach(e=>{e.onfocus=historyPush;e.oninput=()=>{const k=e.dataset.searchList;listDrafts.set(k,e.value);try{const values=parseCandidates(e.value,k);listErrors.delete(k);editParameter(k,values);const scalar=listSpecs[k].scalar;if(scalar)c[scalar]=values[0];analysis.setParameters(c);store();}catch(err){listErrors.set(k,err.message);}e.setAttribute('aria-invalid',String(listErrors.has(k)));$(`[data-list-feedback="${k}"]`).textContent=listErrors.get(k)||candidateHint(k);paint();};});
}
